import {
  BaseGatewayAdapter,
  type GatewayMetadata,
  type GatewayField,
  type InitiateParams,
  type InitiateResult,
  type VerifyResult,
  type Credentials,
  type GatewayContext,
} from '../base';
import { gwJson } from '../kit/http';
import { shaHex } from '../../lib/hash';

const SLUG = "phonepe";

export class PhonepeGateway extends BaseGatewayAdapter {
  metadata(): GatewayMetadata {
    return {
      name: "PhonePe",
      slug: "phonepe",
      version: '1.0.0',
      description: "PhonePe payment gateway integration for OwnPay",
      author: 'OwnPay Gateway Plugin Suite (AGPLv3) — EdgePay port',
      type: 'gateway',
      supported_currencies: [],
      capabilities: ["verification"],
    };
  }

  fields(): GatewayField[] {
    return [
      { name: "merchant_id", label: "Merchant ID", type: "text" as const, required: true },
      { name: "salt_key", label: "Salt Key", type: "password" as const, required: true },
      { name: "salt_index", label: "Salt Index", type: "text" as const, required: true },
    ];
  }

  async initiate(params: InitiateParams, credentials: Credentials, _ctx?: GatewayContext): Promise<InitiateResult> {
    const mode = String(credentials.mode ?? 'sandbox');
    const merchantId = String(credentials["merchant_id"] ?? '');
    const saltKey = String(credentials["salt_key"] ?? '');
    const saltIndex = String(credentials["salt_index"] ?? '');
    const trxId = (params.trx_id ?? '');
    const amount = Math.trunc(Number(String(Math.round(Number(String(Number((params.amount ?? '')))) * 100))));
    const redirectUrl = (params.redirect_url ?? '');
    const url = (String(mode) === String("production")) ? ("https://api.phonepe.com/apis/hermes/pg/v1/pay") : ("https://api-preprod.phonepe.com/apis/pg-sandbox/pg/v1/pay");
    const payload = { ["merchantId"]: merchantId, ["merchantTransactionId"]: trxId, ["merchantUserId"]: `USR_${String(crypto.randomUUID().slice(0, 13))}`, ["amount"]: amount, ["redirectUrl"]: redirectUrl, ["redirectMode"]: "POST", ["paymentInstrument"]: { ["type"]: "PAY_PAGE" } };
    const jsonPayload = String(JSON.stringify(payload));
    const base64 = btoa(String(jsonPayload));
    const checksum = `${String(await shaHex('SHA-256', `${String(base64)}/pg/v1/pay${String(saltKey)}`))}###${String(saltIndex)}`;
    const payloadRequest: Record<string, unknown> = { ["request"]: base64 };
    const res = await gwJson({
      url: url,
      method: 'POST',
      headers: { ["Content-Type"]: "application/json", ["X-VERIFY"]: `${String(checksum)}` },
      body: JSON.stringify(payloadRequest),
      timeoutMs: 15000,
    });
    if (res.data === null) throw new Error(`${SLUG}: invalid response`);
    const d = res.data as Record<string, unknown>;
    const resData = ((d) as Record<string, unknown>)["data"] ?? {};
    const instrumentResponse = ((resData) as Record<string, unknown>)["instrumentResponse"] ?? {};
    const redirectInfo = ((instrumentResponse) as Record<string, unknown>)["redirectInfo"] ?? {};
    const resolvedRedirectUrl = String(((redirectInfo) as Record<string, unknown>)["url"] ?? '');
    return {
          redirect_url: (resolvedRedirectUrl || undefined) as string | undefined,
          session_id: (trxId || undefined) as string | undefined,
        };
  }

  async verify(callbackData: Record<string, unknown>, credentials: Credentials, _ctx?: GatewayContext): Promise<VerifyResult> {
    const cb = callbackData as Record<string, unknown>;
    if (String(cb["merchantTransactionId"] ?? '') === '') {
      return { success: false, gateway_trx_id: '', amount: null, status: 'failed' as const };
    }
    const merchantId = String(credentials["merchant_id"] ?? '');
    const mode = String(credentials.mode ?? 'sandbox');
    const saltKey = String(credentials["salt_key"] ?? '');
    const saltIndex = String(credentials["salt_index"] ?? '');
    const endpoint = `/pg/v1/status/${String(merchantId)}/${String(cb["merchantTransactionId"] ?? cb["transactionId"])}`;
    const url = (String(mode) === String("production")) ? (`https://api.phonepe.com/apis/hermes${String(endpoint)}`) : (`https://api-preprod.phonepe.com/apis/pg-sandbox${String(endpoint)}`);
    const checksum = `${String(await shaHex('SHA-256', `${String(endpoint)}${String(saltKey)}`))}###${String(saltIndex)}`;
    const res = await gwJson({
      url: url,
      method: 'GET',
      headers: { ["X-MERCHANT-ID"]: `${String(merchantId)}`, ["X-VERIFY"]: `${String(checksum)}` },
      timeoutMs: 10000,
    });
    if (res.data === null) {
          return { success: false, gateway_trx_id: '', amount: null, status: 'failed' as const };
        }
    const d = res.data as Record<string, unknown>;
    const resData = ((d) as Record<string, unknown>)["data"] ?? {};
    const ok = String(((d) as Record<string, unknown>)["code"]) === String("PAYMENT_SUCCESS");
    return {
          success: ok,
          gateway_trx_id: String(((resData) as Record<string, unknown>)["transactionId"] ?? ''),
          amount: null,
          status: (ok ? 'completed' : 'failed') as VerifyResult['status'],
          trx_id: String(((cb) as Record<string, unknown>)["merchantTransactionId"] ?? ''),
        };
  }

  async verifyWebhook(_input: { rawBody: string; headers: Record<string, string>; credentials: Credentials }): Promise<boolean> {
    // PORT-SECURITY: upstream accepted these webhooks without a signature
    // check (stub / header-presence only). Ported FAIL-CLOSED: unsigned
    // events are rejected. Payments complete via the signed checkout
    // callback + server-side verify() instead.
    return false;
  }
}
